};
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
#if USE_TEXTURE
  in vec2 uv0;
  uniform sampler2D cc_spriteTexture;
#endif
float drawSparkle(vec2 uv, vec2 center, float radius, float pulse) {
  vec2 d = (uv - center);
  d.x *= 1.7778;
  float dist = length(d);
  float glow = smoothstep(radius * (1.0 + 0.3 * pulse), 0.0, dist);
  float cross = max(smoothstep(0.003, 0.0, abs(d.x)) * smoothstep(radius * 1.6, 0.0, abs(d.y)),
                    smoothstep(0.003, 0.0, abs(d.y)) * smoothstep(radius * 1.6, 0.0, abs(d.x)));
  return glow + cross * 0.5 * pulse;
}
float drawBambooLeaf(vec2 uv, vec2 center, float angle, vec2 size) {
  vec2 d = uv - center;
  d.x *= 1.7778;
  float c = cos(angle);
  float s = sin(angle);
  vec2 r = vec2(d.x * c - d.y * s, d.x * s + d.y * c);
  r.y -= (r.x * r.x) * 3.2;
  float dist = (r.x * r.x) / (size.x * size.x) + (r.y * r.y) / (size.y * size.y);
  return smoothstep(1.0, 0.45, dist);
}
vec4 frag () {
  vec4 o = vec4(1.0, 1.0, 1.0, 1.0);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    #if IS_GRAY
      float gray = 0.2126 * o.r + 0.7152 * o.g + 0.0722 * o.b;
      o.r = o.g = o.b = gray;
    #endif
  #endif
  float t = cc_time.x;
  vec2 rayOrigin = vec2(-0.25, 1.25);
  vec2 rayDir = uv0 - rayOrigin;
  float rayAngle = atan(rayDir.y, rayDir.x);
  float rayWave = sin(rayAngle * 14.0 + t * 0.45) * 0.5 + 0.5;
  float rayWave2 = cos(rayAngle * 22.0 - t * 0.35 + 1.2) * 0.5 + 0.5;
  float rayIntensity = (rayWave * 0.6 + rayWave2 * 0.4);
  float rayFade = smoothstep(1.8, 0.2, length(rayDir)) * smoothstep(0.1, 0.9, uv0.y);
  vec3 sunColor = vec3(1.0, 0.96, 0.72);
  o.rgb += sunColor * rayIntensity * rayFade * 0.18;
  float sparkleSum = 0.0;
  vec2 c1 = vec2(fract(t * 0.035 + 0.15) * 1.1 - 0.05, 0.35 + sin(t * 1.2 + 0.5) * 0.08);
  sparkleSum += drawSparkle(uv0, c1, 0.012, sin(t * 4.0 + 1.0) * 0.5 + 0.5);
  vec2 c2 = vec2(fract(t * 0.042 + 0.52) * 1.1 - 0.05, 0.55 + cos(t * 1.5 + 2.1) * 0.09);
  sparkleSum += drawSparkle(uv0, c2, 0.014, sin(t * 4.5 + 2.5) * 0.5 + 0.5);
  vec2 c3 = vec2(fract(t * 0.030 + 0.85) * 1.1 - 0.05, 0.25 + sin(t * 1.8 + 4.0) * 0.07);
  sparkleSum += drawSparkle(uv0, c3, 0.010, sin(t * 3.8 + 3.8) * 0.5 + 0.5);
  vec2 c4 = vec2(fract(t * 0.048 + 0.33) * 1.1 - 0.05, 0.70 + cos(t * 1.3 + 5.2) * 0.10);
  sparkleSum += drawSparkle(uv0, c4, 0.013, sin(t * 5.0 + 4.2) * 0.5 + 0.5);
  vec2 c5 = vec2(fract(t * 0.028 + 0.68) * 1.1 - 0.05, 0.45 + sin(t * 1.6 + 1.8) * 0.06);
  sparkleSum += drawSparkle(uv0, c5, 0.011, sin(t * 4.2 + 0.9) * 0.5 + 0.5);
  vec3 goldenLight = vec3(1.0, 0.88, 0.35);
  o.rgb += goldenLight * clamp(sparkleSum, 0.0, 1.0) * 0.85;
  vec3 leafColor = vec3(0.42, 0.82, 0.28);
  vec3 leafHighlight = vec3(0.65, 0.92, 0.38);
  float leaf1 = drawBambooLeaf(uv0, vec2(fract(t * 0.070 + 0.20) * 1.3 - 0.15, 0.65 + sin(t * 2.0 + 1.0) * 0.045),
                              sin(t * 2.5 + 1.0) * 0.45 + 0.2, vec2(0.028, 0.008));
  float leaf2 = drawBambooLeaf(uv0, vec2(fract(t * 0.085 + 0.62) * 1.3 - 0.15, 0.48 + cos(t * 2.2 + 3.0) * 0.050),
                              sin(t * 2.8 + 3.0) * 0.50 + 0.1, vec2(0.032, 0.009));
  float leaf3 = drawBambooLeaf(uv0, vec2(fract(t * 0.060 + 0.90) * 1.3 - 0.15, 0.80 + sin(t * 1.8 + 4.5) * 0.040),
                              sin(t * 2.2 + 4.5) * 0.40 + 0.25, vec2(0.025, 0.007));
  float totalLeaves = clamp(leaf1 + leaf2 + leaf3, 0.0, 1.0);
  vec3 finalLeafCol = mix(leafColor, leafHighlight, sin(t * 3.0) * 0.5 + 0.5);
  o.rgb = mix(o.rgb, finalLeafCol, totalLeaves * 0.90);
  o *= color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

